package com.avizero.avidrive.domain;
import jakarta.persistence.*;
@Entity @Table(name="links") public class Link { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(unique=true, nullable=false) public String token; @Column(name="owner_id") public Long ownerId; @Column(name="file_id") public Long fileId; @Column(name="folder_id") public Long folderId; @Column(name="expires_at") public String expiresAt; @Column(name="password_hash") public String passwordHash; @Column(name="can_view") public boolean canView=true; @Column(name="can_download") public boolean canDownload; @Column(name="can_upload") public boolean canUpload; @Column(name="can_delete") public boolean canDelete; @Column(name="can_rename") public boolean canRename; @Column(name="max_file_size_mb") public Long maxFileSizeMb; @Column(name="max_total_size_mb") public Long maxTotalSizeMb; @Column(name="view_count") public Long viewCount=0L; @Column(name="download_count") public Long downloadCount=0L; @Column(name="upload_count") public Long uploadCount=0L; @Column(name="last_accessed_at") public String lastAccessedAt; }
